// Create a counter using closure
const counter = () => {
  let count = 0;

  return () => {
    count++;
    return count;
  };
};

const counter1 = counter();
const counter2 = counter();

console.log(counter1()); // 1
console.log(counter1()); // 2
console.log(counter2()); // 1

// Function implement once()
let once = (fn) => {
  let called = false;

  // ...args = rest operator, collects multiple values into one array
  return function (...args) {
    if (!called) {
      called = true;
      // ...args = spread operator, spreads the array back into individual arguments
      return fn(...args);
    }
  };
};

function greet(name) {
  console.log("Hello", name);
}

const greetOnce = once(greet);

greetOnce("Jeet");  // "Hello Jeet"
greetOnce("Rahul"); // (nothing happens)
greetOnce("Amit");  // (nothing happens)

// Memoization function
const memoize = (fn) => {
  const cache = {};

  return function (...args) {
    // Convert the arguments array into a string key, e.g. [5] -> "[5]"
    const key = JSON.stringify(args);

    if (key in cache) {
      console.log("From Cache");
      return cache[key];
    }

    console.log("Calculating...");
    const result = fn(...args);

    cache[key] = result;

    return result;
  };
};

const square = (n) => {
  return n * n;
};

const memoSquare = memoize(square);

console.log(memoSquare(5));  // "Calculating..." -> 25
console.log(memoSquare(5));  // "From Cache" -> 25
console.log(memoSquare(10)); // "Calculating..." -> 100
console.log(memoSquare(10)); // "From Cache" -> 100

// Function composition
const compose = (...fns) => {
  return function (value) {
    // reduceRight runs the functions from right to left
    return fns.reduceRight((acc, fn) => {
      return fn(acc);
    }, value);
  };
};

const add2 = (x) => x + 2;
const multiply3 = (x) => x * 3;
const subtract1 = (x) => x - 1;

const result = compose(
  subtract1,
  multiply3,
  add2
);

console.log(result(5));
// add2(5) = 7 -> multiply3(7) = 21 -> subtract1(21) = 20

// Higher-order function example
const greett = (name) => {
  return `hello ${name}`;
};

const processUser = (name, callback) => {
  return callback(name);
};

console.log(processUser("Jeet", greett)); // "hello Jeet"

// without currying
const sum = (a, b, c) => {
  return a + b + c;
};

console.log(sum(1, 2, 3)); // 6

// with currying
const sumCurried = (a) => {
  return function (b) {
    return function (c) {
      return a + b + c;
    };
  };
};

console.log(sumCurried(1)(2)(3)); // 6

// infinite currying
const sum = (a) => {
  return function (b) {
    // If called with no argument, stop and return the accumulated total
    if (b === undefined) {
      return a;
    }

    // Otherwise, keep currying with the running total
    return sum(a + b);
  };
};

console.log(sum(1)(2)(3)(4)(5)()); // 15
